// Turns company-facts.md into company-facts.generated.ts, so the facts ship
// inside the app and worker bundles (no file read at runtime on Vercel).
// Run after every edit of company-facts.md:
//   node extensions/ab/content/build-facts.mjs
// A test fails when the generated file is out of date.
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const md = readFileSync(join(here, "company-facts.md"), "utf8").replace(/\r\n/g, "\n");
const out =
  "// Generated by build-facts.mjs from company-facts.md. Do not edit by hand.\n" +
  `export const COMPANY_FACTS = ${JSON.stringify(md)};\n`;
writeFileSync(join(here, "company-facts.generated.ts"), out);
console.log(`company-facts.generated.ts written (${md.length} chars)`);
